// Habillage photographique et navigation tactile ; les parcours précédents sont conservés.
const photoHabitatPositions={cabane:[0,0],perchee:[100,0],container:[0,100],lodge:[100,100]};
function stayPhoto(id){const p=stayCatalog.find(p=>p.id===id);if(id==='luxe'||id==='tiny')return `<img class="photo-cover" src="assets/${id==='luxe'?'maison-l-bois-reference.webp':'tiny-house-solaire-eau.webp'}" alt="Visualisation · ${p.name}" loading="lazy">`;const xy=photoHabitatPositions[id];return `<div role="img" aria-label="Visualisation · ${p.name}" class="photo-tile photo-habitat" style="background-position:${xy[0]}% ${xy[1]}%"></div>`}
function productPhoto(i){let x=i%6*20,y=Math.floor(i/6)*20;return `<span role="img" aria-label="Visuel illustratif · ${esc(products[i].name)}" class="photo-tile photo-food" style="background-position:${x}% ${y}%"></span>`}
const cardsBeforeModern=stayCards;stayCards=function(items){let html=cardsBeforeModern(items);for(const p of items){if(p.id!=='luxe'&&p.id!=='tiny')html=html.replace(habitatArt(p.art),stayPhoto(p.id));}return html};
const detailBeforeModern=stayDetail;stayDetail=function(id){detailBeforeModern(id);const art=$('#modalbody .stay-detail-art');if(art)art.innerHTML=stayPhoto(id);$('#modalbody').insertAdjacentHTML('beforeend','<p class="photo-caption">Visualisation architecturale générée pour le projet · hébergement de démonstration.</p>')};
bikeArt=function(id){const xy={ville:[0,0],vtt:[100,0],electrique:[0,100],cargo:[100,100]}[id];return `<div role="img" aria-label="Visualisation · ${bikeCatalog.find(p=>p.id===id).name}" class="photo-tile photo-bike" style="background-position:${xy[0]}% ${xy[1]}%"></div>`};
const marketCardsBeforeModern=marketCards;marketCards=function(ids){let html=marketCardsBeforeModern(ids);for(const i of ids)html=html.replace(`<span class="mk-food">${products[i].emoji}</span>`,productPhoto(i));return html.replaceAll('SÉLECTION DE DÉMONSTRATION','VISUEL ILLUSTRATIF')};
const productDetailBeforeModern=productDetail;productDetail=function(i){productDetailBeforeModern(i);const art=$('#modalbody .mk-detail-art');if(art){art.innerHTML=productPhoto(i);art.classList.add('modern-product-photo')}$('#modalbody').insertAdjacentHTML('beforeend','<p class="photo-caption">Image de présentation générée · produit et fournisseur fictifs.</p>')};
productsHTML=function(ids){return marketCards(ids)};
scene=function(){return '<img class="scene-photo" src="assets/maison-l-bois-reference.webp" alt="Visualisation du domaine : maison en bois avec terrasse" loading="lazy">'};
miniHouse=function(){return '<img class="mini-house-photo" src="assets/maison-l-bois-reference.webp" alt="Maison en L du Domaine" loading="lazy">'};
function visualBanner(title,copy,asset='jardin-photo.webp'){return `<section class="modern-banner"><img src="assets/${asset}" alt="Visualisation du Domaine" loading="lazy"><div><span class="eyebrow">LE DOMAINE · UNE AUTRE FAÇON DE VIVRE</span><h2>${title}</h2><p>${copy}</p></div></section>`}
const gardenBeforeModern=views.jardin;views.jardin=function(){return visualBanner('Au rythme du vivant.','Cultures, récoltes et ressources, dans un jardin à partager.')+gardenBeforeModern()};
const communityBeforeModern=views.communaute;views.communaute=function(){return visualBanner('Se retrouver. Partager.','Le fil des voisins, les rendez-vous et les idées du collectif.','jardin-photo.webp')+communityBeforeModern()};
const projectBeforeModern=views.projet;views.projet=function(){return visualBanner('Un Domaine à imaginer ensemble.','Dix containers, des habitats singuliers et une vie commune tournée vers la nature.','maison-l-bois-reference.webp')+projectBeforeModern()};
// Une entrée claire vers les ressources directement depuis l'accueil.
const welcomeBeforeModern=views.accueil;views.accueil=function(){return welcomeBeforeModern().replace('<div class="travel-demo">Présentation interactive',`<section class="modern-resource-teaser"><div><span class="eyebrow">RESSOURCES & MOBILITÉ</span><h2>Le confort, en lien avec le vivant.</h2><p>Suivez les panneaux solaires, les litres d’eau et les accès Wi-Fi de chaque habitat. Repérez le parking voitures, motos et vélos sur le plan.</p><a class="btn" href="#ressources">Explorer les habitats connectés ↗</a></div><img src="assets/tiny-house-solaire-eau.webp" alt="Visualisation d’une tiny house avec panneaux et cuve d’eau" loading="lazy"></section><div class="travel-demo">Présentation interactive`)};
function openDomainMenu(){const current=location.hash.slice(1)||'accueil';modal(`<div class="eyebrow">LE DOMAINE · EXPLORER</div><h2 style="margin-top:15px">Où souhaitez-vous aller ?</h2><nav class="mobile-domain-menu" aria-label="Tous les espaces du Domaine">${routes.map(r=>`<a href="#${r[0]}" ${r[0]===current?'aria-current="page"':''} onclick="document.getElementById('modal').close()"><span>${r[1]}</span>${r[2]}<span>↗</span></a>`).join('')}</nav>`)}
function modernNavigation(){const r=location.hash.slice(1)||'accueil';const tabs=[['accueil','⌂','Accueil'],['sejours','⌂','Séjours'],['ville','◇','Plan 3D'],['reservations','▤','Réservations']];let bottom=$('#touch-nav');if(!bottom){bottom=document.createElement('nav');bottom.id='touch-nav';bottom.setAttribute('aria-label','Navigation principale tactile');document.body.appendChild(bottom)}bottom.innerHTML=tabs.map(([id,icon,name])=>`<a href="#${id}" ${id===r?'aria-current="page"':''}><span>${icon}</span><b>${name}</b></a>`).join('')+'<button onclick="openDomainMenu()" aria-label="Ouvrir tous les espaces du Domaine"><span>☰</span><b>Menu</b></button>';let menu=$('#header-domain-menu');if(!menu){menu=document.createElement('button');menu.id='header-domain-menu';menu.textContent='☰ Explorer';menu.setAttribute('aria-label','Ouvrir le menu du Domaine');menu.onclick=openDomainMenu;document.querySelector('.headerend').prepend(menu)}
const basket=$('.mk-basket');if(basket){basket.innerHTML=productPhoto(0);basket.classList.add('modern-basket')}document.querySelectorAll('.mk-bundles button>span').forEach((e,i)=>{e.innerHTML=productPhoto([6,0,29][i]);e.classList.add('modern-bundle-art')});const main=$('#main');main.setAttribute('tabindex','-1');document.documentElement.style.scrollPaddingTop='100px';}
const renderBeforeModern=render;render=function(){renderBeforeModern();modernNavigation()};
window.addEventListener('hashchange',()=>{if(!$('#modal').open)$('#main').focus({preventScroll:true})});
render();
